mapper.insert:
INSERT INTO member (
    member_id, member_password, nickname, member_name, member_phone, member_email, profile_image
) VALUES (
             #{memberId}, #{memberPassword}, #{nickname}, #{memberName},
             #{memberPhone}, #{memberEmail}, #{profileImage}
         )

mapper.select:
SELECT id
FROM member
WHERE member_id = #{memberId}

SELECT member_id
FROM member
WHERE member_name = #{memberName}
  AND member_email = #{memberEmail}
    LIMIT 1

mapper.update:
UPDATE member
nickname = #{nickname}, member_phone = #{memberPhone}, member_email = #{memberEmail}, profile_image = #{profileImage}, updated_at = NOW()
WHERE member_id = #{memberId}

mapper.delete:
DELETE FROM member
WHERE member_status = 'DELETED'
  AND deleted_at <= #{cutoffDate}

mapper.update:
UPDATE member
SET last_login_at = NOW()
WHERE member_id = #{memberId}

UPDATE member
SET member_status = 'DORMANT'
WHERE member_id IN (
    SELECT temp.member_id FROM (
       SELECT member_id
       FROM member
       WHERE member_status = 'ACTIVE'
         AND (
           last_login_at < #{cutoffDate}
               OR (last_login_at IS NULL AND created_at < #{cutoffDate})
           )
   ) AS temp
)
